"""Build static portfolio storefront and 30 demo sites from the shared catalogue."""
import json
from pathlib import Path
from html import escape as e
R=Path(__file__).resolve().parents[1]
items=json.loads((R/'data/portfolio/catalog.json').read_text());cfg=json.loads((R/'data/portfolio/config.json').read_text())
(R/'js/portfolio/catalog.js').write_text('export const templates = '+json.dumps(items,ensure_ascii=False)+';\nexport const config = '+json.dumps(cfg,ensure_ascii=False)+';\n')
def write(path,s):
 s=s.replace('₹2,999',f'₹{cfg["packages"][0]["price"]:,}').replace('₹3,999',f'₹{cfg["packages"][1]["price"]:,}')
 p=R/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
def head(title,desc,path,demo=False,css='store'):
 fonts=('family=DM+Sans:ital,opsz,wght@0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700&family=Manrope:wght@500;600;700&family=DM+Serif+Display:ital@0;1&family=Space+Grotesk:wght@500;600;700&family=IBM+Plex+Mono:wght@400;500' if css=='demo' else 'family=Inter:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700')
 theme='#fafaf7' if css=='store' else '#0c0c0e'
 return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | InfoparkDaily Portfolios</title><meta name="description" content="{e(desc)}"><meta name="robots" content="'+('noindex,nofollow' if demo else 'index,follow')+f'"><link rel="canonical" href="{cfg["site"]}{path}"><meta name="theme-color" content="{theme}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{cfg["site"]}{path}"><meta property="og:image" content="{cfg["site"]}/assets/portfolio/previews/flutter-studio.webp"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/favicon.ico"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?{fonts}&display=swap" rel="stylesheet"><link rel="stylesheet" href="/css/portfolio-{css}.css?v={12 if css=="store" else 10}"><script type="module" src="/js/portfolio/{css}.js?v={12 if css=="store" else 10}"></script></head>'
def art(t,n=0):
 v=t['visual'];title=e(t['projects'][n%3]['title'])
 if v=='photo':return f'<img src="/assets/portfolio/{["landscape","forest","ocean"][n%3]}.jpg" alt="Illustrative { ["mountain landscape","forest canopy","coastal landscape"][n%3]} — sample collection" loading="lazy" width="1200" height="800">'
 if v=='phones':return f'<div class="phone-pair" aria-label="Illustrative mobile interface"><div class="phone"><small>9:41　 ▰</small><span>GOOD MORNING</span><h3>{["A little more<br> daylight.","Your next<br> discovery.","Good things<br> in store."][n%3]}</h3><div class="phone-disc">{["☀","↗","◒"][n%3]}</div><div class="phone-row">Today’s collection <b>→</b></div><div class="phone-row">A moment for you <b>＋</b></div></div><div class="phone phone-back"><small>YOUR WEEK</small><h3>Make space<br> for the good.</h3><div class="bars"><i></i><i></i><i></i><i></i><i></i></div><p>MON　TUE　WED</p></div></div>'
 if v in ['code','research']:return f'<div class="code-window"><div>● ● ● <span>{title.lower().replace(" ","-")}.md</span></div><pre><span>// {title}</span>\n\nexport const approach = {{\n  question: "What matters?",\n  method: "Make it clear",\n  quality: "Test the details",\n  next: "Keep learning"\n}};\n\n<span>→ Read the project story below</span></pre></div>'
 if v=='diagram':return '<div class="architecture"><span>CLIENT EXPERIENCE</span><b>↓</b><div><span>API GATEWAY</span><span>AUTH LAYER</span></div><b>↓</b><div><span>SERVICE</span><span>QUEUE</span><span>DATA</span></div><small>Illustrative architecture</small></div>'
 if v in ['chart','dashboard']:return f'<div class="dashboard"><div class="dash-nav">◈ {title}<span>SAMPLE DATA</span></div><div class="dash-heading"><span>Activity overview</span><strong>Patterns, at a glance.</strong></div><div class="bars">'+''.join(f'<i style="--bar:{h}%"></i>' for h in [28,44,36,62,51,76,66,91])+'</div><div class="dash-foot">MON　　 TUE　　 WED　　 THU　　 FRI</div></div>'
 if v=='checklist':return '<div class="test-panel"><small>RELEASE READINESS / SAMPLE</small><h3>Every detail<br> deserves a check.</h3><p>✓ Keyboard navigation</p><p>✓ Responsive layouts</p><p>✓ Clear failure states</p><p>○ Review & document</p></div>'
 if v in ['poster','social','brand']:return f'<div class="poster-art poster-{n%3}"><span>STUDIO EXPERIMENT / 0{n+1}</span><strong>{["COMMON<br> GROUND.","TYPE<br>& PLAY.","MAKE<br> ROOM."][n%3] if v!="brand" else ["aure.","Maison<br> Paper","Still<br> House"][n%3]}</strong><div class="art-circle"></div><small>{title} — illustrative design study</small></div>'
 if v=='motion':return '<div class="motion-art"><span>SHAPE / SHIFT</span><div class="motion-shape"></div><strong>Ideas<br> in motion.</strong><small>Illustrative motion study</small></div>'
 if v=='article':return f'<div class="article-art"><small>FIELD NOTES / 0{n+1}</small><span>“</span><h3>{title}</h3><p>A sample reading experience.<br> Thoughts, carefully considered.</p></div>'
 if v=='roadmap':return '<div class="roadmap-art"><small>PRODUCT DIRECTION</small><h3>Discover → Decide → Deliver</h3><div><span>NOW<br><b>Understand the need</b></span><span>NEXT<br><b>Test the approach</b></span><span>LATER<br><b>Learn & iterate</b></span></div></div>'
 if v=='people':return '<div class="people-art"><span>PEOPLE, FIRST.</span><div><i>Welcome</i><i>Listen</i><i>Grow</i></div><strong>A place<br> to belong.</strong></div>'
 return f'<div class="browser-art"><div class="browser-top">● ● ●<span>{title.lower().replace(" ","")}.example</span></div><div class="browser-content"><small>A DESIGN EXPLORATION</small><h3>{["Make room<br> for a good day.","A fresh<br> perspective.","Good things,<br>well made."][n%3]}</h3><span class="art-pill">Explore the idea ↗</span><div class="browser-orb"></div></div></div>'
def project(t,n):
 p=t['projects'][n];return f'<article class="work-item" id="project-{n+1}"><div class="work-art">{art(t,n)}</div><div class="work-copy"><span class="tiny">0{n+1} / ILLUSTRATIVE PROJECT</span><h3>{e(p["title"])}</h3><p>{e(p["description"])}</p><details><summary>Read the '+('article' if t['visual']=='article' else 'project story')+' <span>↗</span></summary><div><h4>The starting point</h4><p>'+e(p['description'])+f'</p><h4>My approach</h4><p>This fictional study explores how {e(t["skills"][0].lower())} and {e(t["skills"][1].lower())} can support a clearer experience. The work begins with defining the need, exploring alternatives, and documenting a focused solution.</p><h4>Reflection</h4><p>The sample demonstrates how to explain a contribution and its tradeoffs. Your website will use your actual process, evidence, responsibilities, and approved results.</p></div></details></div></article>'
def demo(t):
 slug=t['slug'];layout=t['layout'];dark='Dark' in t['styleTags'];initials=''.join(w[0] for w in t['person'].split())
 h=head(t['name']+' — fictional website demo',t['description'],f'/portfolio/demo/{slug}/',True,'demo')+f'<body class="demo layout-{layout} '+('dark' if dark else 'light')+f'" data-template="{slug}"><a class="skip" href="#main">Skip to content</a><div class="demo-notice">FICTIONAL DEMO · Names, projects, career details and visuals are illustrative. <a href="/portfolio/templates/{slug}/" target="_top">Personalise this design ↗</a></div><header class="demo-header"><a class="personal-brand" href="#intro"><span class="initials">{initials}</span><span data-person>{t["person"]}</span></a><button class="demo-menu" aria-expanded="false" aria-controls="demo-nav">Menu ＋</button><nav id="demo-nav" aria-label="Portfolio sections"><a href="#work">'+('Writing' if t['visual']=='article' else 'Work')+'</a><a href="#about">About</a><a href="#journey">'+('Education' if t['category']=='Freshers' else 'Journey')+'</a><a href="#contact">Let’s connect ↗</a></nav></header><main id="main">'
 title=f'<div class="intro-copy"><p class="overline" data-profession>{e(t["profession"])}</p><h1>{e(t["headline"])}</h1><p class="intro-description">I’m <span data-person>{t["person"]}</span>. I bring curiosity, care, and a practical approach to {e(t["profession"].lower())} work. Here’s a selection of what I’m exploring.</p><div class="intro-actions"><a class="demo-button" href="#work">Explore my '+('writing' if t['visual']=='article' else 'work')+' ↗</a><a href="#about">A little about me ↓</a></div></div>'
 heroart=f'<div class="hero-art">{art(t)}</div>'
 extras={
 'terminal':'<div class="terminal-line"><span>~/portfolio</span> $ hello_world <b>● OPEN TO CONVERSATIONS</b></div>',
 'devices':'<div class="hero-tags"><span>FLUTTER</span><span>ANDROID + iOS</span><a href="#demo-download">Sample store links ↓</a></div>',
 'oversize':'<div class="hero-marquee">CODE.　CRAFT.　CURIOSITY.　↗</div>',
 'blueprint':'<div class="blueprint-index"><span>01 / SYSTEMS</span><span>02 / ARCHITECTURE</span><span>03 / TRADEOFFS</span></div>',
 'bento':'<div class="bento-note"><strong>Building across<br> the whole stack.</strong><span>INTERFACE ↔ SERVICE ↔ DATA</span></div>',
 'readme':'<div class="readme-index"><code>README.md</code><a href="#work">/ repositories</a><a href="#skills">/ toolkit</a><a href="#contact">/ contribute</a></div>',
 'report':'<div class="report-caption"><b>THE ANALYSIS NOTEBOOK</b><span>Explore → Explain → Communicate</span></div>',
 'paper':'<div class="paper-abstract"><b>ABSTRACT</b><p>A living collection of experiments, research questions, and lessons from building with data. Reproducibility and honest limitations come first.</p></div>',
 'console':'<div class="console-status"><span>● SYSTEM PROFILE</span><code>plan → provision → observe</code><span>DESIGNED FOR CLARITY</span></div>',
 'dossier':'<div class="dossier-label"><span>PUBLIC RESEARCH FILE</span><strong>SEC / PROFILE</strong><span>ETHICAL PRACTICE · DOCUMENTED LEARNING</span></div>',
 'checklist':'<div class="quality-ribbon"><span>STRATEGY</span><span>AUTOMATION</span><span>EXPLORATORY TESTING</span></div>',
 'casebook':'<p class="hero-footnote">SELECTED CASE STUDIES ↓　 /　 THINKING MADE VISIBLE</p>',
 'journal':'<div class="journal-note"><span>FIELD JOURNAL</span><p>Observe without assumptions.<br> Listen before deciding.</p></div>',
 'poster':'<div class="poster-strip">INDEPENDENT THINKING　✳　VISUAL EXPRESSION　✳</div>',
 'atelier':'<div class="atelier-seal">Form.<br> Feeling.<br> Meaning.</div>',
 'cinema':'<div class="showreel"><video controls preload="none" poster="/assets/portfolio/motion-poster.webp" aria-label="Illustrative abstract motion showreel"><source src="/assets/portfolio/sample-motion.webm" type="video/webm"></video><p>PLAY THE SAMPLE SHOWREEL · An abstract demo clip, not client work.</p></div>',
 'photo':'<p class="photo-caption">AN ILLUSTRATIVE PHOTO JOURNAL / LANDSCAPES & EVERYDAY LIGHT</p>',
 'campaign':'<div class="campaign-strip"><b>THE BRIEF</b><p>Find the story.<br> Understand the audience.<br> Make the next step clear.</p></div>',
 'social':'<div class="social-notes"><span>Strategy with substance.</span><span>Stories with personality.</span><span>Content with purpose.</span></div>',
 'writer':'<div class="writer-byline"><span>ESSAYS / PEOPLE / DESIGN</span><p>A notebook for things worth thinking about.</p></div>',
 'creator':'<div class="creator-topics"><span>PLACES</span><span>PEOPLE</span><span>PROCESS</span><span>POSSIBILITIES</span></div>',
 'roadmap':'<div class="product-principles"><span>01 Understand</span><span>02 Prioritise</span><span>03 Learn</span></div>',
 'corporate':'<div class="business-line"><span>OPERATIONS</span><span>STRATEGY</span><span>PARTNERSHIPS</span></div>',
 'people':'<div class="people-note"><span>01 / WELCOME</span><p>Good conversations.<br> Stronger connections.</p></div>',
 'graduate':'<div class="graduate-note"><b>THE NEXT CHAPTER</b><p>A collection of projects, lessons,<br>and things I’m excited to build.</p></div>',
 'campus':'<div class="campus-sticker">ALWAYS<br> LEARNING ↗</div>',
 'bridge':'<div class="bridge-line"><span>OPERATIONS</span><b>→</b><span>UX DESIGN</span></div>',
 'services':'<div class="service-menu"><a href="#expertise">01 / Design</a><a href="#expertise">02 / Development</a><a href="#expertise">03 / Digital presence</a></div>',
 'signature':'<div class="signature-mark">Vikram.</div>',
 'executive':'<div class="executive-note"><span>A PERSONAL PERSPECTIVE</span><p>Leadership is a practice.<br> Learning is the constant.</p></div>'}
 # Every layout has a dedicated composition and distinct content order.
 before=layout in ['terminal','readme','console','dossier','writer','bridge','report'];art_first=layout in ['photo','people','atelier'];noheroart=layout in ['paper','journal','writer','signature','executive','dossier','readme','graduate']
 h+=f'<section id="intro" class="intro">'+(extras[layout] if before else '')+(heroart if art_first else '')+title+('' if art_first or noheroart or layout=='cinema' else heroart)+(extras[layout] if not before else '')+'</section>'
 skills='<section id="skills" class="skills-section"><p class="overline">MY TOOLKIT</p><div>'+''.join(f'<span>{e(x)}</span>' for x in t['skills'])+'</div></section>'
 work='<section id="work" class="work-section"><div class="section-title"><p class="overline">SELECTED '+('WRITING' if t['visual']=='article' else 'WORK')+'</p><h2>'+({'article':'A few ideas worth sharing.','photo':'Collected moments.','phones':'Made for the everyday.','research':'Questions I’m exploring.'}.get(t['visual'],'Thinking, put into practice.'))+'</h2></div><div class="work-grid">'+''.join(project(t,n) for n in range(3))+'</div></section>'
 about=f'<section id="about" class="about-section"><div class="about-monogram" aria-hidden="true">{initials}</div><div><p class="overline">BEHIND THE WORK</p><h2>A little curiosity.<br> A lot of care.</h2><p>I’m <span data-person>{t["person"]}</span>, a fictional {e(t["profession"].lower())} in this template demonstration. This space is for your story: what draws you to your work, what you value, and what you want to do next.</p><p>Your finished portfolio will use your approved biography, images, and real experience. Optional sections can be removed when they don’t apply.</p><details id="demo-download"><summary>Resume & sample links ↗</summary><p>This is a demo. No real resume or app-store listing is attached. Your personalised website can link to your approved resume PDF, GitHub, LinkedIn, Behance, and published apps.</p></details></div></section>'
 journey='<section id="journey" class="journey-section"><div class="section-title"><p class="overline">THE JOURNEY / FICTIONAL EXAMPLES</p><h2>'+('Learning in practice.' if t['category']=='Freshers' else 'Experience shapes perspective.')+'</h2></div><div class="journey-list">'
 for date,title,desc in ([('Sample education','Relevant degree / qualification','Your institution, graduation year, and relevant coursework go here.'),('Sample project work','Academic & independent projects','Describe your actual contribution, tools, and learning.'),('Optional internship','An early professional experience','Include only internships or responsibilities you actually held.')] if t['category']=='Freshers' else [('Sample current role',t['profession']+' · Example Studio','A fictional role showing where your responsibilities and professional contribution belong.'),('Sample earlier role','Project contributor · Example Collective','Use your actual employer, dates, and specific responsibilities.'),('Education & learning','Your qualification · Your institution','Replace with approved education details and relevant continued learning.')]):
  journey+=f'<article><span>{date}</span><div><h3>{title}</h3><p>{desc}</p></div></article>'
 journey+='</div><details class="certifications"><summary>Certifications & continued learning ＋</summary><p>No certification is claimed in this demo. Add your verified qualification, issuer, date, and verification link, or remove this section.</p></details></section>'
 expertise='<section id="expertise" class="expertise"><p class="overline">WAYS I CAN CONTRIBUTE</p><div>'+''.join(f'<article><span>0{i+1}</span><h3>{skill}</h3><p>A space to describe your approach, relevant experience, and the kind of collaboration you welcome.</p></article>' for i,skill in enumerate(t['skills'][:3]))+'</div></section>'
 recipe={ 'terminal':[skills,work,about,journey], 'devices':[work,skills,about,journey], 'oversize':[skills,work,journey,about], 'blueprint':[expertise,work,skills,journey,about], 'bento':[skills,about,work,journey], 'readme':[about,work,journey,skills], 'report':[work,about,skills,journey], 'paper':[about,work,skills,journey], 'console':[skills,work,expertise,journey,about], 'dossier':[work,skills,journey,about], 'checklist':[expertise,skills,work,about,journey], 'casebook':[work,about,journey,skills], 'journal':[work,journey,about,skills], 'poster':[work,skills,expertise,about,journey], 'atelier':[about,work,skills,journey], 'cinema':[work,skills,about,journey], 'photo':[work,about,skills,journey], 'campaign':[expertise,work,journey,skills,about], 'social':[skills,work,expertise,about,journey], 'writer':[work,about,journey,skills], 'creator':[work,expertise,skills,about,journey], 'roadmap':[expertise,journey,work,skills,about], 'corporate':[about,journey,skills,work], 'people':[about,expertise,work,journey,skills], 'graduate':[skills,journey,work,about], 'campus':[work,journey,about,skills], 'bridge':[about,skills,work,journey], 'services':[expertise,work,about,journey,skills], 'signature':[about,expertise,work,journey,skills], 'executive':[about,journey,work,skills] }
 h+=''.join(recipe[layout])
 h+='<section id="contact" class="contact-section"><div><p class="overline">START A CONVERSATION</p><h2>Have something<br> in mind?</h2><p>This is a sample contact form. It stays in your browser and never sends a message.</p><span class="sample-contact">Your approved contact links go here.</span></div><form id="demo-form"><label>Your name<input name="name" required autocomplete="off" maxlength="100"></label><label>Email<input name="email" type="email" required autocomplete="off" maxlength="180"></label><label>Your message<textarea name="message" rows="3" required maxlength="1500"></textarea></label><button class="demo-button" type="submit">Try the demo form ↗</button><p role="status" id="demo-status"></p></form></section></main><footer class="demo-footer"><span data-person>'+t['person']+'</span><span>FICTIONAL TEMPLATE DEMONSTRATION</span><a href="#intro">Back to top ↑</a></footer></body></html>'
 return h
for t in items:write(f'portfolio/demo/{t["slug"]}/index.html',demo(t))
def header(signin=False,page='home'):
 cur=lambda key: ' aria-current="page"' if page==key else ''
 return '<a class="skip" href="#main">Skip to content</a><header class="store-header"><div class="width"><a class="store-brand" href="/portfolio/"><img src="/assets/logo-infoparkdaily.png" alt="" width="36" height="36"><span>InfoparkDaily<small>PORTFOLIO WEBSITES</small></span></a><button id="store-menu" aria-expanded="false" aria-controls="store-nav">Menu</button><nav id="store-nav" aria-label="Career tools"><a href="/resume-builder/">Resume builder</a><a href="/ats-checker/">ATS checker</a><a href="/resume-builder/templates/">Resume templates</a><a href="/portfolio/"'+cur('home')+'>Portfolio</a><a href="/portfolio/templates/"'+cur('templates')+'>Templates</a><a href="/jobs/">Jobs</a><span id="account-nav">'+('' if signin else '<a class="store-signin" href="/portfolio/sign-in/">Sign in</a>')+'</span></nav></div></header>'
def footer():return '<footer class="width store-footer"><div><a class="store-brand" href="/portfolio/">InfoparkDaily Portfolios</a><p>Your skills. Your work. Your own website.</p></div><nav aria-label="Footer"><a href="/portfolio/templates/">Templates</a><a href="/portfolio/terms/">Package & renewal terms</a><a href="/privacy/">Privacy</a><a href="/jobs/">Find jobs</a></nav><p>© 2026 InfoparkDaily · Personalised by our team.</p></footer>'+dialog()
def dialog():return '<dialog id="order-dialog"><form id="order-form"><button class="close-dialog" type="button" aria-label="Close package selection">×</button><p class="eyebrow">YOUR NEXT CHAPTER</p><h2>Let’s make this<br> website yours.</h2><div id="selected-template"></div><fieldset><legend>Choose your package</legend>'+''.join(f'<label class="package-option"><input type="radio" name="package" value="{p["id"]}"'+(' checked' if i==0 else '')+f'><span><strong>{p["name"]} — ₹{p["price"]:,}</strong><small>{p["description"]}</small></span></label>' for i,p in enumerate(cfg['packages']))+'</fieldset><label class="owned-domain"><input type="checkbox" name="existing"> I already have a domain</label><label id="domain-field" hidden>Preferred or existing domain<input name="domain" placeholder="yourname.com" maxlength="253" autocomplete="off"><small>We’ll check availability and confirm eligible options on WhatsApp.</small></label><label>Your name <small>(optional)</small><input name="name" maxlength="100" autocomplete="name" placeholder="What should we call you?"></label><p class="policy-note">'+cfg['domainPolicy']+'</p><p class="policy-note">'+cfg['policy']+'</p><a class="text-link" href="/portfolio/terms/">Read package & renewal terms ↗</a><button class="button" type="submit">Continue on WhatsApp ↗</button><p class="policy-note">Opens a prefilled conversation. You send the message yourself. No payment or reservation is made here.</p></form></dialog><p id="store-status" class="sr-only" role="status"></p>'
def card(t):return f'<article class="template-card" data-slug="{t["slug"]}" data-category="{t["category"]}"><div class="template-image"><a class="template-thumb" href="{t["previewPath"]}" aria-label="Preview {t["name"]}"><img src="{t["thumbnail"]}" alt="{t["name"]} actual website demo preview" width="1200" height="900" loading="lazy"><span class="preview-pill">Preview</span></a><button class="favourite" data-favourite="{t["slug"]}" aria-label="Save {t["name"]} to favourites" aria-pressed="false">♡</button>'+('<span class="editorial-tag">Featured</span>' if t['featured'] else '')+f'</div><div class="template-meta"><div class="template-title"><h3><a href="/portfolio/templates/{t["slug"]}/">{t["name"]}</a></h3><span>{t["styleTags"][0]}</span></div><p class="profession">{e(t["profession"])} portfolio</p><p class="card-blurb">{t["description"]}</p><div class="card-prices">Website ₹{cfg["packages"][0]["price"]:,} <span>· With eligible domain ₹{cfg["packages"][1]["price"]:,}</span></div><div class="card-actions"><a href="{t["previewPath"]}">Preview Website</a><a class="card-choose" href="/portfolio/templates/{t["slug"]}/">Choose Template →</a></div></div></article>'
def featured_html():
 lead=[t for t in items if t['featured']]
 if not lead: return ''
 first=card(lead[0]).replace('class="template-card"','class="template-card is-spotlight"',1)
 side=''.join(card(t) for t in lead[1:3])
 rest=''.join(card(t) for t in lead[3:])
 return '<div class="featured-stage">'+first+'<div class="featured-side">'+side+'</div></div><div class="template-grid featured-more">'+rest+'</div>'
def gallery(full=True):return '<section class="width section" id="collection"><div class="section-heading"><div><p class="eyebrow">THE COLLECTION</p><h2>Find the design that feels like you.</h2></div><p>30 considered designs. One place for your next chapter.</p></div><form id="gallery-controls" class="gallery-controls" role="search"><label class="search-field"><span>Search templates</span><input type="search" name="q" placeholder="Try Flutter, writing, projects…"></label><label>Profession<select name="category"><option value="">All professions</option>'+''.join(f'<option>{x}</option>' for x in ['Developers','Designers','Freshers','Freelancers','Creators','Professionals'])+'</select></label><label>Style<select name="style"><option value="">All styles</option>'+''.join(f'<option>{x}</option>' for x in ['Minimal','Bold','Editorial','Dark','Light'])+'</select></label><label>Sort<select name="sort"><option value="featured">Featured</option><option value="newest">Newest collection additions</option><option value="az">A–Z</option></select></label><label class="shortlist"><input name="saved" type="checkbox"> Favourites</label><button type="reset" class="reset">Reset filters</button></form><div class="gallery-result"><p id="result-count" role="status">30 templates</p><span>Personalisation service · No editor subscription</span></div><div class="template-grid" id="template-grid">'+''.join(card(t) for t in items)+'</div><div id="empty-state" hidden><h3>No templates match just yet.</h3><p>Try a different profession or remove a filter.</p><button class="button" data-reset>Reset filters</button></div></section>'
faq=[('What is included in ₹2,999?','A personalised one-page website based on any listed design, responsive layouts, your professional content, approved resume/contact links, and basic SEO. A new domain is excluded. Final project limits and hosting terms are confirmed in writing.'),('What is included in ₹3,999?','The portfolio website plus one eligible standard-price custom domain for the first year, subject to availability and the registration allowance confirmed in your quote.'),('Can I choose any listed template?','Yes. Every listed template has a complete demo. Choose one design and our team personalises it with your content.'),('Is the domain included forever?','No. Only the first year of an eligible registration is included in the domain package. Domain and hosting renewals are disclosed before you order.'),('Which domains are eligible?','Eligibility depends on availability, extension, and registration cost. The covered cost limit and qualifying extensions must be confirmed in your written quote. Premium names and higher-priced extensions need a separate quote.'),('Can I use a domain I already own?','Yes, enquire about connecting a supported existing domain with the ₹2,999 package. We confirm registrar access and hosting compatibility before work starts.'),('Is hosting included?','Hosting provider, included period, HTTPS support, and costs must be confirmed in your quote. We do not promise free or lifetime hosting.'),('What are the renewal charges?','We disclose the domain and hosting renewal estimates separately before payment, along with the renewal manager and expiry dates. Future provider prices may change.'),('How long will my website take?','We confirm a delivery estimate after reviewing your content and scope. The timeline depends on complete materials, revisions, and domain setup.'),('What content do I need to provide?','Your name, headline, biography, skills, education, real project details, experience if applicable, images, resume PDF, and approved public contact links. A checklist is provided after enquiry.'),('Can I use the service as a fresher?','Yes. Fresh Start and Campus Portfolio put education, academic projects, and internships first. We remove sections that do not apply.'),('Can I change colours and images?','Yes. Name, copy, profile image, accent colour, projects, skills, and contact links can be personalised within the selected layout.'),('How many revisions are included?','Two consolidated rounds are the proposed allowance. The exact revision count and what constitutes a round are confirmed in your written quote before payment.'),('Can I request a completely custom design?','Yes, as a separate quote. Template personalisation does not include a full redesign, custom applications, or unlimited new sections.'),('Can I update the website later?','Later changes can be arranged at an agreed cost. A CMS, editing dashboard, unlimited updates, and self-service editor are not included.'),('Can I add more projects later?','Yes, subject to the agreed layout and a change quote. Up to six project entries are the proposed starting scope, confirmed before ordering.'),('Will the website work on phones?','The listed demos include responsive desktop, tablet, and mobile layouts. You can inspect them using the preview device controls.'),('Can I connect LinkedIn, GitHub, Behance, and my resume?','Yes. We use your approved profile links and final resume PDF. You explicitly approve which email address and phone number can appear publicly.'),('Is business email included?','No. Mailboxes and paid email services require a separate arrangement. Your existing email can be linked.'),('Who owns the domain?','The customer must be recorded as the domain owner. Registrar access, management, renewal responsibility, and transfer steps are agreed before purchase.'),('Can I move the website elsewhere?','Handover files, repository access, licences, hosting portability, and any migration work are recorded in the service agreement.'),('What happens if I do not renew?','Domain or hosting expiry can make your website unavailable. Any grace periods, retention, or restoration fees depend on the provider and are explained when choosing the service.'),('What are the cancellation and refund terms?','Cancellation stages, refundable amounts, and non-refundable third-party costs must be agreed in writing before payment. This enquiry does not place a paid order.'),('Are taxes included?','Tax treatment and the final payable total are confirmed in the written quote. Do not make payment until the total and scope are agreed.')]
def faqs(all=False):return '<section class="width section" id="faqs"><div class="section-heading"><p class="eyebrow">BEFORE YOU BEGIN</p><h2>Good questions. Clear answers.</h2></div><div class="faq-list">'+''.join(f'<details><summary>{q}<span>＋</span></summary><p>{a}</p></details>' for q,a in (faq if all else faq[:8]))+'</div>'+('' if all else '<a class="text-link" href="/portfolio/terms/#faqs">More answers about revisions, ownership & delivery ↗</a>')+'</section>'
def pricing():return '<section class="pricing-band" id="pricing"><div class="width section"><div class="section-heading"><div><p class="eyebrow">A CLEAR STARTING POINT</p><h2>Your website. Your choice.</h2></div><p>Personalised by our team. No self-service editor to learn.</p></div><div class="pricing-grid">'+''.join(f'<article><p class="eyebrow">{p["name"]}</p><h3>₹{p["price"]:,}</h3><p>{p["description"]}</p><ul>'+''.join(f'<li>{x}</li>' for x in cfg['scope'])+('<li>First-year eligible domain, subject to written confirmation</li>' if p['id']=='domain' else '<li>Provided subdomain or supported existing domain, as agreed</li>')+f'</ul><button class="button" data-order data-package="{p["id"]}">Choose this package ↗</button></article>' for p in cfg['packages'])+'</div><div class="pricing-policy"><p>'+cfg['domainPolicy']+'</p><p>'+cfg['policy']+'</p><a href="/portfolio/terms/">Package scope & ownership details ↗</a></div></div></section>'
def process():return '<section class="width section" id="how-it-works"><div class="section-heading"><p class="eyebrow">FROM TEMPLATE TO YOURS</p><h2>You bring the story. We bring it together.</h2></div><ol class="steps">'+''.join(f'<li><span>0{i+1}</span><h3>{title}</h3><p>{desc}</p></li>' for i,(title,desc) in enumerate([('Choose your design','Preview complete websites and find a design that fits your work.'),('Select your package','Choose website only or website with an eligible domain. Agree scope and charges.'),('Share your content','Send your resume, projects, images, and approved public contact links.'),('Review and launch','Review your personalised preview, use the agreed revisions, and approve launch.')]))+'</ol></section>'
h=head('Your skills. Your work. Your own website.','Explore 30 portfolio website designs, preview complete demos, and enquire on WhatsApp. Personalised by our team from ₹2,999.','/portfolio/')+'<body>'+header()+'<main id="main"><section class="store-hero"><div class="width hero-grid"><div class="hero-copy"><p class="hero-kicker">Portfolio websites · From ₹2,999</p><h1>Your skills. Your work. Your own <span>website.</span></h1><p class="hero-lead">Choose a complete design. We personalise it with your projects, experience, and contact details — then you share one link.</p><div class="hero-actions"><a class="button" href="/portfolio/templates/">Browse templates</a><a class="button secondary" href="#how-it-works">How it works</a></div><p class="hero-meta"><strong>₹2,999</strong> website <span>·</span> <strong>₹3,999</strong> with eligible domain <span>·</span> Personalised by our team</p></div><div class="hero-visual"><div class="hero-visual-label"><span>Flutter Studio sample</span><a href="/portfolio/preview/flutter-studio/">Open preview →</a></div><div class="hero-shot"><a class="hero-shot-main" href="/portfolio/preview/flutter-studio/"><img src="/assets/portfolio/previews/flutter-studio.webp" width="1200" height="900" alt="Flutter Studio portfolio template preview" fetchpriority="high"></a><a class="hero-shot-phone" href="/portfolio/preview/flutter-studio/"><img src="/assets/portfolio/previews/flutter-studio-mobile.webp" width="390" height="844" alt="Flutter Studio on mobile"></a></div></div></div></section><div class="width"><section class="audience"><p class="eyebrow">Made for</p><nav aria-label="Audience">'+''.join(f'<a href="/portfolio/templates/?category={x}">{x}</a>' for x in ['Developers','Designers','Freshers','Freelancers','Creators','Professionals'])+'</nav></section></div><section class="width section featured-block"><div class="section-heading"><div><p class="eyebrow">Featured designs</p><h2>Six starting points. Thirty to explore.</h2></div><a class="text-link" href="/portfolio/templates/">View all 30 designs</a></div><div class="template-grid">'+''.join(card(t) for t in items if t['featured'])+'</div></section>'+gallery()+''+process()+pricing()+'<section class="width section personalisation"><div class="section-heading"><div><p class="eyebrow">A PERSONALISATION DEMONSTRATION</p><h2>Same foundation. Entirely your story.</h2></div><p>Names, initials, accent colours, skills, projects, and contact labels can change within the selected layout. These examples are fictional.</p></div><div class="personalisation-controls"><button class="active" data-personalise="original" aria-pressed="true">Neha’s sample</button><button data-personalise="alternate" aria-pressed="false">Arun’s sample</button></div><iframe id="personalise-frame" title="Flutter Studio personalisation demonstration" src="/portfolio/demo/flutter-studio/" loading="lazy"></iframe><p class="policy-note">Profile photos can replace initials where the selected layout supports them. Layout redesigns require a separate quote.</p></section>'+faqs()+'<section class="final-cta"><div class="width"><p class="eyebrow">YOUR NEXT MOVE</p><h2>You have the experience. Give it a place to stand out.</h2><div><a class="button" href="/portfolio/templates/">Choose My Template ↗</a><button class="text-link" data-general-enquiry>Ask on WhatsApp ↗</button></div></div></section></main>'+footer()+'</body></html>'

